dataTableFormat:
{
  "is multi section": "true",
  "sections": [
    {
      "section id": "pigean_overall_gene",
      "header": "Connecting gene sets to phenotypes | Browse by gene",
      "data point unused": {
        "type": "bioindex",
        "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/query/pigean-overall-gene?q=$gene$model",
        "continue url": "https://cfde-dev.hugeampkpnbi.org/api/bio/cont?token=",
        "parameters": [
          "gene",
          "model"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "data point": {
        "type": "bioindex",
        "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/",
        "index": "pigean-overall-gene",
        "parameters": [
          "gene",
          "model"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "pre filters": [
        {
          "field": "Marginal effect",
          "value": 0.01,
          "type": "search greater than"
        }
      ],
      "search parameters": [
        {
          "parameter": "gene",
          "label": "Gene",
          "type": "input",
          "values": "kp genes"
        },
        {
          "parameter": "model",
          "label": "Model",
          "type": "list",
          "values": [
            {
              "label": "CFDE",
              "value": "cfde"
            },
            {
              "label": "Mouse",
              "value": "mouse"
            }
          ]
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Model",
            "raw field": "gene_set_size"
          },
          {
            "type": "raw",
            "field name": "Anchor gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Joint effect",
            "raw field": "beta",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "Marginal effect",
            "raw field": "beta_uncorrected",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "Gene set",
            "raw field": "gene_set"
          },
          {
            "type": "raw",
            "field name": "Phenotype name",
            "raw field": "phenotype_name"
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Study",
            "raw field": "study"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "Combined score",
            "raw field": "combined"
          },
          {
            "type": "raw",
            "field name": "Direct support",
            "raw field": "log_bf"
          },
          {
            "type": "raw",
            "field name": "Gene set evidence",
            "raw field": "prior"
          },
          {
            "type": "join multi",
            "field name": "Hypothesis",
            "fields to join": [
              "phenotype",
              "gene_set"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "join multi",
            "field name": "Genes in gene set",
            "fields to join": [
              "Phenotype",
              "Gene set"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "join multi",
            "field name": "Gene set x Phenotype",
            "fields to join": [
              "Gene set",
              "Phenotype"
            ],
            "join by": [
              " x "
            ]
          }
        ],
        "top rows": [
          "Phenotype",
          "Gene set",
          "Model",
          "Source",
          "Joint effect",
          "Marginal effect",
          "Anchor gene",
          "Genes in gene set",
          "Hypothesis"
        ],
        "tool tips": {
          "Phenotype": "Phenotype identifier from the Association to Function Knowledge Portal. See the Searchable options page to map identifiers to descriptive terms.",
          "Gene set": "Gene set identifier",
          "Source": "Source of the gene set",
          "Joint effect": "The joint effect of a gene set measures its relevance to the phenotype when considered jointly across all gene sets in the model; this measure quantifies whether a gene set is maximally predictive of a phenotype compared to all other gene sets in the model. All gene set effects are expressed in units of log-odds of probabilities. Consider the following thresholds for interpreting joint gene set effects: >0.01 = significant, >0.1 = strongly significant, and >1.0 = among the strongest for any phenotype and any gene set. Genes with high marginal effects but weak joint effects are relevant to the phenotype in question but likely correlated with another gene set(s) that are more relevant to the phenotype.",
          "Marginal effect": "The marginal effect of a gene set measures its relevance to the phenotype when considered in isolation; this is the default measure by which the table is sorted and is the analog of traditional enrichment statistics. All gene set effects are expressed in units of log-odds of probabilities. Consider the following thresholds for interpreting marginal gene set effects: >0.01 = significant, >0.1 = strongly significant, and >1.0 = among the strongest for any phenotype and any gene set.",
          "Anchor gene": "Gene searched",
          "Genes in gene set": "View all genes in the gene set, sorted by relevance to the phenotype.",
          "Hypothesis": "Use GPT-4o to suggest how the 10 genes within this set most associated with the phenotype are related to the phenotype, using the gene set as context to the query. The subtable shows the response from GPT-4o as well as the input prompt, so that it can be copied into your favorite ChatBot to initiate further lines of inquiry."
        },
        "column formatting": {
          "Hypothesis": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://llm.hugeamp.org/llm?phenotype=$phenotype&gene_set=$geneSet&gene_limit=10&add_context=1",
                "parameters": [
                  "phenotype",
                  "geneSet"
                ],
                "parameters type": "replace",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Hypothesis",
                    "raw field": "gpt_response"
                  },
                  {
                    "type": "raw",
                    "field name": "LLM Query",
                    "raw field": "query"
                  }
                ],
                "top rows": [
                  "LLM Query",
                  "Hypothesis"
                ]
              }
            }
          },
          "Source": {
            "type": [
              "link with parameters"
            ],
            "link to": "/r/kc_gene_set_browser_source?",
            "parameters": {
              "source": "Source",
              "model": "Model"
            }
          },
          "Anchor gene": {
            "type": [
              "link with parameters"
            ],
            "link to": "/r/kc_gene_set_browser_gene?",
            "parameters": {
              "gene": "Anchor gene",
              "model": "Model"
            }
          },
          "Genes in gene set": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/",
                "index": "pigean-joined-gene-set",
                "parameters": [
                  "phenotype",
                  "geneSet"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Gene",
                    "raw field": "gene"
                  },
                  {
                    "type": "raw",
                    "field name": "Model",
                    "raw field": "gene_set_size"
                  },
                  {
                    "type": "raw",
                    "field name": "Combined genetic support",
                    "raw field": "combined"
                  },
                  {
                    "type": "raw",
                    "field name": "Direct support",
                    "raw field": "log_bf"
                  },
                  {
                    "type": "raw",
                    "field name": "Gene set evidence",
                    "raw field": "prior"
                  },
                  {
                    "type": "raw",
                    "field name": "Source",
                    "raw field": "source"
                  }
                ],
                "top rows": [
                  "Gene",
                  "Model",
                  "Combined genetic support",
                  "Direct support",
                  "Gene set evidence"
                ],
                "column formatting": {
                  "Gene": {
                    "type": [
                      "link with parameters"
                    ],
                    "link to": "/r/kc_gene_set_browser_gene?",
                    "parameters": {
                      "gene": "Gene",
                      "model": "Model"
                    }
                  }
                }
              }
            }
          },
          "Phenotype": {
            "type": [
              "link with parameters"
            ],
            "link to": "/r/kc_gene_set_browser_phenotype?",
            "parameters": {
              "phenotype": "Phenotype",
              "model": "Model"
            }
          },
          "Gene set": {
            "type": [
              "link with parameters"
            ],
            "link to": "/r/kc_gene_set_browser_gene_set?",
            "parameters": {
              "geneSet": "Gene set",
              "model": "Model"
            }
          }
        }
      },
      "visualizers": {
        "wrapper type": "tabs",
        "visualizers": [
          {
            "label": "by Gene set x Phenotype",
            "type": "scatter plot",
            "star key": null,
            "render type": "single plot",
            "group by": "Gene",
            "color by": "Source",
            "y axis field": "Joint effect",
            "y axis label": "Joint effect",
            "x axis field": "Marginal effect",
            "x axis label": "Marginal effect",
            "ticks decimal point": "4",
            "render by": "Gene set x Phenotype",
            "hover content": [
              "Phenotype",
              "Gene set",
              "Study",
              "Joint effect",
              "Marginal effect"
            ],
            "height": 250,
            "width": 750,
            "plot margin": {
              "left": 60,
              "right": 20,
              "top": 40,
              "bottom": 50,
              "bump": 5
            }
          }
        ]
      },
      "filters": [
        {
          "field": "Phenotype",
          "label": "Phenotype",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "Gene set",
          "label": "Gene set",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "checkbox",
          "label in bubble": "true",
          "uncheck": [
            "gene_set_list_mouse",
            "gene_set_list_msigdb_nohp"
          ]
        },
        {
          "field": "Joint effect",
          "label": "Joint effect(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Marginal effect",
          "label": "Marginal effect(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        }
      ]
    }
  ]
}

pageStyle:
.text-align-center{
   text-align:center;
}
.fixed-header {
 position: relative !important;
}
.multi-section-card {
margin-bottom: 20px;
}
#rp_tabs_contents { 
/* background: none !important;
  border: none; */ }

#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
    width: 830px !important;
    margin-left: 0 !important;
}

.byor-single-search-results-wrapper {
    width: 830px !important;
margin-left: 0 !important;
}

span.Tclin > strong {
padding: 0 10px;
    border: solid 2px #337ab7;
    border-radius: 5px;
}
span.Tchem > strong {
padding: 0 10px;
    border: solid 2px #5bc0de;
    border-radius: 5px;
}
span.Tbio > strong {
padding: 0 10px;
    border: solid 2px #ffb259;
    border-radius: 5px;
}
span.Tdark > strong {
padding: 0 10px;
    border: solid 2px #d32f2f;
    border-radius: 5px;
}

.info-card-row {
    margin-bottom: 15px;
}

.info-card-row > .row-key {
    width: 150px; display: inline-block; vertical-align: top;
}

.info-card-row > .row-value {
    width: calc(100% - 150px);  display: inline-block;
}

#byor_single_search { border-color: #ff7f00; }

.volcano-plot-content {
text-align: center;
}


.multi-page-search-wrapper { /*display: none;*/}

.multi-page-search-wrapper.in-section-ui { display: block;}



/* alex css begin */

.single-search-wrapper {
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.context-btns-wrapper {
  display: flex;
  gap: 10px;
}
.context-btns-wrapper .btn {
  text-wrap: nowrap;
  background: white;
  color: black;
  border: 1px solid #ccc;
}
.context-btns-wrapper .btn.active {
  background: #ff802c !important;
  border: 1px solid #ccc !important;
}
.context-btns-wrapper .btn.btn-warning {
  background: #ccc;
}
.context-btns-wrapper .btn.btn-warning:hover {
  background: #bbb;
}

.dataset-page-header {
  background: none;
  border: 0;
  display: none;
}

.kp-tabs-contents:has(.multi-page-search-wrapper) {
  /* background: none;
  border: none; */
}

.col-md-12:has(.multi-page-search-wrapper) {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.col-md-12{
  height: fit-content;
}

.tab-ui-wrapper {
  margin: 0;
  background: none;
  border-bottom: 0;
  padding: 0;
}
.tab-content-group {
  background: white;
  border-radius: 0 10px 10px 10px;
  border: 1px solid #ddd;
  padding: 10px 20px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
}

button.show-hide-section, button.capture-data {
  display: none;
}

.tab-content-group:has(.multi-section) {
  padding: 10px 0;
}

.multi-section {
  background: white;
  padding: 10px 20px 30px 20px;
  border-radius: 10px;
  border-bottom: 0;
}

.multi-section .section-header {
  padding: 10px 5px;
}
.multi-section .section-header h4 {
  font-size: 22px;
}
.section-header h4 small {
  font-size: 22px !important;
  padding-left: 10px;
    border-left: solid 1px #dddddd;
    margin-left: 5px;
}

.table-total-rows {
  padding-top: 3px;
}
.table-ui-wrapper {
  display: flex;
  align-items: baseline;
  gap: 5px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
  color: #5a5a5a;
  background: #ddd;
}
.tab-ui-wrapper .tab-ui-tab:hover {
  color: black;
}
.table-ui-wrapper .number-per-page {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}
.convert-2-csv {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}

/* tables */
.mbm-plot-content {
  margin: 0 0 20px 0;
}
.research-data-table-wrapper {
  margin: 0 15px;
}
table.research-data-table {
  border: 0 !important;
  text-align: left;
}
.research-data-table tbody:nth-child(odd) {
  background: #f9f9f9;
}

#section_IDG_gene .research-data-table td {
  border: 0 !important;
  padding: 10px 10px;
  vertical-align: top !important;
}

#section_IDG_gene .egl-table-page-ui-wrapper, #section_IDG_gene .table-total-rows, #section_IDG_gene .table-ui-wrapper {
  display: none;
}

#section_IDG_gene .table-wrapper { margin-top: 25px; }

th.Visit.Pharos { width: 120px !important; }

.research-data-table td {
  border: 0 !important;
  padding: 3px 10px;
  line-height: 1.5em;
}
.research-data-table > thead > tr > th {
  border: 0 !important;
  padding: 5px 10px;
}
.research-data-table > thead > tr > th.sortable-th {
  color: black;
}
[class*="cell-weight"] {
  padding-left: 10px;
}
.sortable-th:after {
  content: '';
  background: none;
  width: 10px;
  height: 10px;
  position: absolute;
  margin: 0 0 0 5px;
  bottom: 7px;
  border-right: 5px solid transparent;
  border-left: 5px solid transparent;
  border-top: 5px solid #b4b4b4;
  border-bottom: 5px solid transparent;
}
table.feature-table {
  border-bottom: 3px solid #cccccc;
}
.feature-table > tr > th.feature-title-th {
  background-color: #cccccc !important;
}
table.feature-table tr:nth-child(odd) {
  background: white;
}
table.feature-table th.feature-th-0 {
  background-color: #eeeeee !important;
  border-left: 0 !important;
  padding: 0.3rem 10px;
  border-bottom: 1px solid #ccc !important;
}

#section_general_gene_info_function .row-value.Function {
  font-size: 16px;
  line-height: 26px;
}

/* colors */  
table a {
  color: #ff6600 !important;
}
.show-evidence-btn {
  background: #ffa02c !important;
  border: 0;
}
.show-evidence-btn:hover {
  background: #dc5800 !important;
  color:white !important;
}
.tab-ui-wrapper .tab-ui-tab.loading > .flag {
  color: #ffaa2c;
}
.page-item.active .page-link {
  background-color: #ffa02c;
}
.page-link {
  color: #ff6600;
}

img.dcc-logo {
  width: 100px;
  height: 100px;
  object-fit: contain;
  margin-top: -15px;
}

/* page descriptions */
.page-description-content {
  /* padding-left: 175px; */
  margin: 10px;
  min-height: 70px;
}
.page-description-content h4 {
  font-size: 16px;
  font-weight: bold;
}
.page-description-content p {
  font-size: 14px;
  line-height: normal;
  margin: 0;
  margin-bottom: 8px;
}

/* filters, search blocks */
.multi-page-search-wrapper {
  height: fit-content;
}
div.filtering-ui-wrapper {
  border: 0;
  border-radius: 0;
  border-left: 3px solid #ff6600;
  margin: 0;
}
.filtering-ui-wrapper>h4.card-title {
  color: #ff6600;
}
.filtering-ui-wrapper.search-criteria {
  /*border: 0;
  background: #efefef;*/
  border-left: 3px solid #34679a;
}
.filtering-ui-wrapper.search-criteria>h4.card-title {
  color: #34679a;
}
.search-fields-wrapper .search-field:empty {
  display: none;
}
.filtering-ui-content .btn-primary {
  background: #ff7f00;
  border: 1px solid transparent;
}
.filtering-ui-content .btn-primary:hover {
  background: #dc5800;
}
.filtering-ui-content .btn-warning {
  background: #ccc;
  border: 1px solid transparent;
}
.filtering-ui-content .btn-primary:hover {
  background: #bbb;
}

.research-data-table td {
overflow-wrap: anywhere;
}

/*center search bar with wrapper*/
.single-search-wrapper {
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: center;
}
/*dont make search bar take up whole wrapper */
.byor-single-search-wrapper{
width:fit-content !important;
}
/* hode context buttons */
.context-btns-wrapper {
  display: none;
  gap: 10px;
}

/*set SS link colors */
a.ss-explore {
color: #007bff !important;
}

.required-parameters-label {
display: none !important;
}

.required-parameter {
  border: none !important;
  margin-left: 10px !important;
}
